contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMin) public payable {
        uint beforeMin = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool minReverted;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            minReverted = true;
        } else {
            minReverted = false;
        }

        assert(minReverted && c.MinSum() == beforeMin);
    }

    receive() external payable {}
}

